import{_ as t,o as n,c as s,ag as r}from"./chunks/framework.ySAk_w31.js";const m=JSON.parse(`{"title":"Glossaire des mots-clés IA","description":"","frontmatter":{},"headers":[],"relativePath":"handout-09-glossaire.md","filePath":"handout-09-glossaire.md","handout":{"fichier":"handout-09-glossaire.md","markdown":"# Handout — Glossaire des mots-clés IA\\n\\n**Développeur IA — Foundation · Zenika · glossaire**\\n\\nUne phrase par terme : les mêmes mots, avec le même sens, que dans la formation business, puis les termes propres aux développeurs.\\n\\nLes termes techniques anglais sont gardés (harness, tools, context window, skill) : ce sont ceux que vous entendrez dans les outils et les réunions.\\n\\n## Tronc commun : les bases\\n\\n_Ouverture et module 1_\\n\\n| Terme                                  | En une phrase                                                                                                                                                                                                                                                                         |\\n| -------------------------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| **LLM** (Large Language Model)         | Modèle entraîné sur d'énormes volumes de texte, qui génère une réponse en prédisant le mot suivant.                                                                                                                                                                                   |\\n| **Token**                              | Morceau de mot traité par le modèle ; c'est aussi l'unité de facturation (≈ ¾ de mot en anglais).                                                                                                                                                                                     |\\n| **Hallucination**                      | Réponse fausse mais présentée avec assurance et vraisemblance.                                                                                                                                                                                                                        |\\n| **Knowledge cutoff** (date de coupure) | Date à laquelle s'arrêtent les données d'entraînement du modèle ; il ignore tout ce qui s'est passé après, sauf s'il fait une recherche web.                                                                                                                                          |\\n| **Assistant**                          | Le produit qu'on utilise au quotidien (ChatGPT, Copilot, Claude.ai, Gemini) : une interface posée sur un harness, autour d'un modèle.                                                                                                                                                 |\\n| **Harness**                            | Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.                                                                                                                                |\\n| **Tools**                              | Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (_tool calling_).                                                                                                                                                  |\\n| **MCP** (Model Context Protocol)       | Standard pour brancher de nouveaux tools sur un assistant : applications et données de l'entreprise.                                                                                                                                                                                  |\\n| **Agent**                              | Modèle qui enchaîne lui-même des actions avec des tools, en boucle, jusqu'à atteindre un objectif : c'est la **boucle agentique** (modèle + tools + boucle + objectif, que le harness fait tourner). Les éditeurs utilisent aussi « agent » pour de simples assistants personnalisés. |\\n| **Boucle agentique** (agent loop)      | Le cycle demande → le modèle choisit un tool → le harness l'exécute → le résultat entre dans le contexte → on recommence si besoin.                                                                                                                                                   |\\n\\n## Tronc commun : demander et capitaliser\\n\\n_Ouverture, modules 2 à 4_\\n\\n| Terme                                                    | En une phrase                                                                                                                                                                                                                                                                                     |\\n| -------------------------------------------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| **Prompt**                                               | La demande envoyée au modèle, consignes comprises.                                                                                                                                                                                                                                                |\\n| **Rewind**                                               | Revenir corriger la demande de départ plutôt qu'empiler des corrections dans la conversation.                                                                                                                                                                                                     |\\n| **Instructions personnalisées / assistant personnalisé** | Consignes enregistrées une fois et réappliquées : toujours (instructions personnalisées) ou dans un espace dédié (GPT, Projet Claude, agent Copilot).                                                                                                                                             |\\n| **Skill**                                                | Savoir-faire emballé (consignes, modèles, exemples, parfois des scripts) que l'assistant charge **à la demande**, quand la tâche correspond. Plus léger que des instructions permanentes, partageable dans une équipe. Claude parle d'« Agent Skills » ; d'autres assistants ont des équivalents. |\\n| **Vibe coding**                                          | Produire vite un prototype en langage naturel, sans regarder le code ; parfait pour explorer, insuffisant pour livrer.                                                                                                                                                                            |\\n| **AI-driven development**                                | Développement logiciel où l'IA écrit beaucoup de code, sous la direction et le contrôle d'ingénieurs.                                                                                                                                                                                             |\\n\\n## Tronc commun : le contexte\\n\\n_Modules 1, 4 et 5_\\n\\n| Terme                                    | En une phrase                                                                                                                |\\n| ---------------------------------------- | ---------------------------------------------------------------------------------------------------------------------------- |\\n| **Context window**                       | Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.           |\\n| **Session**                              | Une conversation ; elle accumule du contexte, utile ou parasite.                                                             |\\n| **Mémoire**                              | Informations que l'assistant réinjecte automatiquement d'une session à l'autre (profil, préférences) ; souvent désactivable. |\\n| **Grounding**                            | Ancrer la réponse dans des sources vérifiables plutôt que dans la « mémoire » du modèle.                                     |\\n| **RAG** (Retrieval-Augmented Generation) | Technique de grounding : on cherche les bons extraits de documents internes et on les ajoute au contexte avant de répondre.  |\\n\\n## Tronc commun : risques et coûts\\n\\n_Module 5_\\n\\n| Terme                              | En une phrase                                                                                                                                                                   |\\n| ---------------------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| **Human-in-the-loop**              | Un humain qualifié valide la sortie de l'IA _avant_ qu'elle soit utilisée.                                                                                                      |\\n| **Prompt injection**               | Instructions malveillantes cachées dans un contenu (email, document, page web) qui détournent un assistant.                                                                     |\\n| **Fuite de données**               | Données confidentielles envoyées à un assistant non maîtrisé (version grand public).                                                                                            |\\n| **Cache**                          | Mise en mémoire du début du contexte pour ne pas le repayer plein tarif à chaque message (il est relu à prix réduit) ; changer de modèle ou de tools en cours de route le perd. |\\n| **Plafond de dépense** (spend cap) | Limite de budget configurée pour éviter les factures surprises.                                                                                                                 |\\n\\n## Termes propres aux développeurs : la machine\\n\\n_Modules 1 et 2_\\n\\n| Terme                | En une phrase                                                                                                                                     |\\n| -------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| **Agent de code**    | Agent qui lit, modifie et exécute du code dans un dépôt (Copilot, Claude Code, Codex, Cursor…).                                                   |\\n| **Non-déterminisme** | La même demande peut donner des sorties différentes : une réponse est un tirage, pas un calcul.                                                   |\\n| **Autorégression**   | Le modèle génère token par token, chaque token produit devenant l'entrée du suivant : ce qu'il a écrit oriente ce qu'il écrira.                   |\\n| **System prompt**    | Consignes que le harness place en tête de chaque appel, avant les instructions projet et la conversation.                                         |\\n| **Tool definitions** | Nom, description et paramètres de chaque tool, envoyés au modèle à chaque appel : ils pèsent dans la context window et se lisent comme un prompt. |\\n| **Permissions**      | Les actions autorisées à l'agent (lire, écrire, lancer une commande, accéder au réseau).                                                          |\\n\\n## Termes propres aux développeurs : cadrer, produire, capitaliser\\n\\n_Modules 2 à 4_\\n\\n| Terme                                 | En une phrase                                                                                                                                                                                     |\\n| ------------------------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| **Instructions projet** (\`AGENTS.md\`) | Fichier versionné dans le dépôt, chargé à chaque session : conventions, commandes, pièges. C'est l'équivalent dev des instructions personnalisées.                                                |\\n| **Demande initiale**                  | Premier message de la session, cadré pour la tâche du jour : objectif, fichiers clés, commandes, invariants, pièges. Pour une tâche longue, on l'écrit dans un fichier rechargé à chaque session. |\\n| **Invariant**                         | Règle qui doit rester vraie quoi que fasse l'agent (un contrat d'API, une règle métier, un test qui doit passer).                                                                                 |\\n| **Plan d'exécution**                  | Liste d'étapes vérifiables que l'agent propose avant de coder, et que le dev corrige avant de le laisser faire.                                                                                   |\\n| **Niveau d'autonomie**                | Ce que l'agent peut faire sans demander : proposer, modifier après accord, ou agir seul.                                                                                                          |\\n| **Revue IA**                          | Relecture d'un diff par un agent ; elle aide l'humain, elle ne décide pas du merge.                                                                                                               |\\n| **Brownfield / greenfield**           | Code existant à faire évoluer / projet partant de zéro.                                                                                                                                           |\\n| **Progressive disclosure**            | L'agent ne voit d'abord que le nom et la description d'une skill, et ne charge son contenu que quand il en a besoin.                                                                              |\\n\\n## Termes propres aux développeurs : garder la main\\n\\n_Module 5_\\n\\n| Terme                                              | En une phrase                                                                                                                                                                                    |\\n| -------------------------------------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\\n| **Context rot** (en business : dérive de contexte) | Dégradation des réponses quand la context window se remplit d'ajouts, de corrections et d'informations périmées ou contradictoires : la session reste crédible mais s'éloigne du besoin initial. |\\n| **Compaction**                                     | Résumé automatique ou demandé de la session pour libérer de la context window.                                                                                                                   |\\n| **Lost in the middle**                             | Le modèle exploite moins bien ce qui se trouve au milieu d'un long contexte.                                                                                                                     |\\n| **Trio létal**                                     | Données privées + contenu non fiable + capacité d'envoyer vers l'extérieur : la combinaison qui rend une fuite possible.                                                                         |\\n| **Shadow AI**                                      | Usage d'outils d'IA non validés par l'entreprise.                                                                                                                                                |\\n"}}`),o={name:"handout-09-glossaire.md"};function a(d,e,i,u,l,c){return n(),s("div",null,[...e[0]||(e[0]=[r('<p class="zh-type">glossaire</p><h1 id="handout-glossaire-des-mots-cles-ia" tabindex="-1">Glossaire des mots-clés IA <a class="header-anchor" href="#handout-glossaire-des-mots-cles-ia" aria-label="Permalink to &quot;Handout — Glossaire des mots-clés IA&quot;">​</a></h1><p>Une phrase par terme : les mêmes mots, avec le même sens, que dans la formation business, puis les termes propres aux développeurs.</p><p>Les termes techniques anglais sont gardés (harness, tools, context window, skill) : ce sont ceux que vous entendrez dans les outils et les réunions.</p><h2 id="tronc-commun-les-bases" tabindex="-1">Tronc commun : les bases <a class="header-anchor" href="#tronc-commun-les-bases" aria-label="Permalink to &quot;Tronc commun : les bases&quot;">​</a></h2><p><em>Ouverture et module 1</em></p><table tabindex="0"><thead><tr><th>Terme</th><th>En une phrase</th></tr></thead><tbody><tr><td><strong>LLM</strong> (Large Language Model)</td><td>Modèle entraîné sur d’énormes volumes de texte, qui génère une réponse en prédisant le mot suivant.</td></tr><tr><td><strong>Token</strong></td><td>Morceau de mot traité par le modèle ; c’est aussi l’unité de facturation (≈ ¾ de mot en anglais).</td></tr><tr><td><strong>Hallucination</strong></td><td>Réponse fausse mais présentée avec assurance et vraisemblance.</td></tr><tr><td><strong>Knowledge cutoff</strong> (date de coupure)</td><td>Date à laquelle s’arrêtent les données d’entraînement du modèle ; il ignore tout ce qui s’est passé après, sauf s’il fait une recherche web.</td></tr><tr><td><strong>Assistant</strong></td><td>Le produit qu’on utilise au quotidien (ChatGPT, Copilot, Claude.ai, Gemini) : une interface posée sur un harness, autour d’un modèle.</td></tr><tr><td><strong>Harness</strong></td><td>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</td></tr><tr><td><strong>Tools</strong></td><td>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (<em>tool calling</em>).</td></tr><tr><td><strong>MCP</strong> (Model Context Protocol)</td><td>Standard pour brancher de nouveaux tools sur un assistant : applications et données de l’entreprise.</td></tr><tr><td><strong>Agent</strong></td><td>Modèle qui enchaîne lui-même des actions avec des tools, en boucle, jusqu’à atteindre un objectif : c’est la <strong>boucle agentique</strong> (modèle + tools + boucle + objectif, que le harness fait tourner). Les éditeurs utilisent aussi « agent » pour de simples assistants personnalisés.</td></tr><tr><td><strong>Boucle agentique</strong> (agent loop)</td><td>Le cycle demande → le modèle choisit un tool → le harness l’exécute → le résultat entre dans le contexte → on recommence si besoin.</td></tr></tbody></table><h2 id="tronc-commun-demander-et-capitaliser" tabindex="-1">Tronc commun : demander et capitaliser <a class="header-anchor" href="#tronc-commun-demander-et-capitaliser" aria-label="Permalink to &quot;Tronc commun : demander et capitaliser&quot;">​</a></h2><p><em>Ouverture, modules 2 à 4</em></p><table tabindex="0"><thead><tr><th>Terme</th><th>En une phrase</th></tr></thead><tbody><tr><td><strong>Prompt</strong></td><td>La demande envoyée au modèle, consignes comprises.</td></tr><tr><td><strong>Rewind</strong></td><td>Revenir corriger la demande de départ plutôt qu’empiler des corrections dans la conversation.</td></tr><tr><td><strong>Instructions personnalisées / assistant personnalisé</strong></td><td>Consignes enregistrées une fois et réappliquées : toujours (instructions personnalisées) ou dans un espace dédié (GPT, Projet Claude, agent Copilot).</td></tr><tr><td><strong>Skill</strong></td><td>Savoir-faire emballé (consignes, modèles, exemples, parfois des scripts) que l’assistant charge <strong>à la demande</strong>, quand la tâche correspond. Plus léger que des instructions permanentes, partageable dans une équipe. Claude parle d’« Agent Skills » ; d’autres assistants ont des équivalents.</td></tr><tr><td><strong>Vibe coding</strong></td><td>Produire vite un prototype en langage naturel, sans regarder le code ; parfait pour explorer, insuffisant pour livrer.</td></tr><tr><td><strong>AI-driven development</strong></td><td>Développement logiciel où l’IA écrit beaucoup de code, sous la direction et le contrôle d’ingénieurs.</td></tr></tbody></table><h2 id="tronc-commun-le-contexte" tabindex="-1">Tronc commun : le contexte <a class="header-anchor" href="#tronc-commun-le-contexte" aria-label="Permalink to &quot;Tronc commun : le contexte&quot;">​</a></h2><p><em>Modules 1, 4 et 5</em></p><table tabindex="0"><thead><tr><th>Terme</th><th>En une phrase</th></tr></thead><tbody><tr><td><strong>Context window</strong></td><td>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</td></tr><tr><td><strong>Session</strong></td><td>Une conversation ; elle accumule du contexte, utile ou parasite.</td></tr><tr><td><strong>Mémoire</strong></td><td>Informations que l’assistant réinjecte automatiquement d’une session à l’autre (profil, préférences) ; souvent désactivable.</td></tr><tr><td><strong>Grounding</strong></td><td>Ancrer la réponse dans des sources vérifiables plutôt que dans la « mémoire » du modèle.</td></tr><tr><td><strong>RAG</strong> (Retrieval-Augmented Generation)</td><td>Technique de grounding : on cherche les bons extraits de documents internes et on les ajoute au contexte avant de répondre.</td></tr></tbody></table><h2 id="tronc-commun-risques-et-couts" tabindex="-1">Tronc commun : risques et coûts <a class="header-anchor" href="#tronc-commun-risques-et-couts" aria-label="Permalink to &quot;Tronc commun : risques et coûts&quot;">​</a></h2><p><em>Module 5</em></p><table tabindex="0"><thead><tr><th>Terme</th><th>En une phrase</th></tr></thead><tbody><tr><td><strong>Human-in-the-loop</strong></td><td>Un humain qualifié valide la sortie de l’IA <em>avant</em> qu’elle soit utilisée.</td></tr><tr><td><strong>Prompt injection</strong></td><td>Instructions malveillantes cachées dans un contenu (email, document, page web) qui détournent un assistant.</td></tr><tr><td><strong>Fuite de données</strong></td><td>Données confidentielles envoyées à un assistant non maîtrisé (version grand public).</td></tr><tr><td><strong>Cache</strong></td><td>Mise en mémoire du début du contexte pour ne pas le repayer plein tarif à chaque message (il est relu à prix réduit) ; changer de modèle ou de tools en cours de route le perd.</td></tr><tr><td><strong>Plafond de dépense</strong> (spend cap)</td><td>Limite de budget configurée pour éviter les factures surprises.</td></tr></tbody></table><h2 id="termes-propres-aux-developpeurs-la-machine" tabindex="-1">Termes propres aux développeurs : la machine <a class="header-anchor" href="#termes-propres-aux-developpeurs-la-machine" aria-label="Permalink to &quot;Termes propres aux développeurs : la machine&quot;">​</a></h2><p><em>Modules 1 et 2</em></p><table tabindex="0"><thead><tr><th>Terme</th><th>En une phrase</th></tr></thead><tbody><tr><td><strong>Agent de code</strong></td><td>Agent qui lit, modifie et exécute du code dans un dépôt (Copilot, Claude Code, Codex, Cursor…).</td></tr><tr><td><strong>Non-déterminisme</strong></td><td>La même demande peut donner des sorties différentes : une réponse est un tirage, pas un calcul.</td></tr><tr><td><strong>Autorégression</strong></td><td>Le modèle génère token par token, chaque token produit devenant l’entrée du suivant : ce qu’il a écrit oriente ce qu’il écrira.</td></tr><tr><td><strong>System prompt</strong></td><td>Consignes que le harness place en tête de chaque appel, avant les instructions projet et la conversation.</td></tr><tr><td><strong>Tool definitions</strong></td><td>Nom, description et paramètres de chaque tool, envoyés au modèle à chaque appel : ils pèsent dans la context window et se lisent comme un prompt.</td></tr><tr><td><strong>Permissions</strong></td><td>Les actions autorisées à l’agent (lire, écrire, lancer une commande, accéder au réseau).</td></tr></tbody></table><h2 id="termes-propres-aux-developpeurs-cadrer-produire-capitaliser" tabindex="-1">Termes propres aux développeurs : cadrer, produire, capitaliser <a class="header-anchor" href="#termes-propres-aux-developpeurs-cadrer-produire-capitaliser" aria-label="Permalink to &quot;Termes propres aux développeurs : cadrer, produire, capitaliser&quot;">​</a></h2><p><em>Modules 2 à 4</em></p><table tabindex="0"><thead><tr><th>Terme</th><th>En une phrase</th></tr></thead><tbody><tr><td><strong>Instructions projet</strong> (<code>AGENTS.md</code>)</td><td>Fichier versionné dans le dépôt, chargé à chaque session : conventions, commandes, pièges. C’est l’équivalent dev des instructions personnalisées.</td></tr><tr><td><strong>Demande initiale</strong></td><td>Premier message de la session, cadré pour la tâche du jour : objectif, fichiers clés, commandes, invariants, pièges. Pour une tâche longue, on l’écrit dans un fichier rechargé à chaque session.</td></tr><tr><td><strong>Invariant</strong></td><td>Règle qui doit rester vraie quoi que fasse l’agent (un contrat d’API, une règle métier, un test qui doit passer).</td></tr><tr><td><strong>Plan d’exécution</strong></td><td>Liste d’étapes vérifiables que l’agent propose avant de coder, et que le dev corrige avant de le laisser faire.</td></tr><tr><td><strong>Niveau d’autonomie</strong></td><td>Ce que l’agent peut faire sans demander : proposer, modifier après accord, ou agir seul.</td></tr><tr><td><strong>Revue IA</strong></td><td>Relecture d’un diff par un agent ; elle aide l’humain, elle ne décide pas du merge.</td></tr><tr><td><strong>Brownfield / greenfield</strong></td><td>Code existant à faire évoluer / projet partant de zéro.</td></tr><tr><td><strong>Progressive disclosure</strong></td><td>L’agent ne voit d’abord que le nom et la description d’une skill, et ne charge son contenu que quand il en a besoin.</td></tr></tbody></table><h2 id="termes-propres-aux-developpeurs-garder-la-main" tabindex="-1">Termes propres aux développeurs : garder la main <a class="header-anchor" href="#termes-propres-aux-developpeurs-garder-la-main" aria-label="Permalink to &quot;Termes propres aux développeurs : garder la main&quot;">​</a></h2><p><em>Module 5</em></p><table tabindex="0"><thead><tr><th>Terme</th><th>En une phrase</th></tr></thead><tbody><tr><td><strong>Context rot</strong> (en business : dérive de contexte)</td><td>Dégradation des réponses quand la context window se remplit d’ajouts, de corrections et d’informations périmées ou contradictoires : la session reste crédible mais s’éloigne du besoin initial.</td></tr><tr><td><strong>Compaction</strong></td><td>Résumé automatique ou demandé de la session pour libérer de la context window.</td></tr><tr><td><strong>Lost in the middle</strong></td><td>Le modèle exploite moins bien ce qui se trouve au milieu d’un long contexte.</td></tr><tr><td><strong>Trio létal</strong></td><td>Données privées + contenu non fiable + capacité d’envoyer vers l’extérieur : la combinaison qui rend une fuite possible.</td></tr><tr><td><strong>Shadow AI</strong></td><td>Usage d’outils d’IA non validés par l’entreprise.</td></tr></tbody></table>',25)])])}const g=t(o,[["render",a]]);export{m as __pageData,g as default};
